package controllers;

import entities.User;
import javafx.collections.FXCollections;
import javafx.fxml.FXML;
import javafx.scene.control.ComboBox;
import javafx.scene.control.Label;
import javafx.stage.FileChooser;
import services.UserService;
import utils.SceneNavigator;
import utils.UserSession;

import java.io.File;
import java.util.List;

public class FaceIdAdminManagementController {
    @FXML
    private ComboBox<User> userBox;

    @FXML
    private Label faceIdStatusLabel;

    @FXML
    private Label selectedImageLabel;

    @FXML
    private Label messageLabel;

    private final UserService userService = new UserService();
    private File selectedImageFile;

    @FXML
    public void initialize() {
        if (UserSession.getCurrentUserRole() != User.AdminType.ADMIN_ACCOUNT) {
            setMessage("Access denied: admin role required.", false);
            setEditingEnabled(false);
            return;
        }

        List<User> users = userService.getUsersEditableByCurrentUser(UserSession.getCurrentUserRole());
        userBox.setItems(FXCollections.observableArrayList(users));
        userBox.getSelectionModel().selectedItemProperty().addListener((obs, oldUser, newUser) -> refreshFaceStatus(newUser));

        if (!users.isEmpty()) {
            userBox.getSelectionModel().selectFirst();
        } else {
            faceIdStatusLabel.setText("Aucun utilisateur disponible.");
            setEditingEnabled(false);
        }
    }

    @FXML
    private void handlePickImage() {
        FileChooser chooser = new FileChooser();
        chooser.setTitle("Choisir une image de visage");
        chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter(
                "Images", "*.png", "*.jpg", "*.jpeg", "*.bmp", "*.webp"
        ));
        File picked = chooser.showOpenDialog(userBox.getScene() == null ? null : userBox.getScene().getWindow());
        if (picked == null) {
            return;
        }
        selectedImageFile = picked;
        selectedImageLabel.setText(picked.getName());
    }

    @FXML
    private void handleAddFaceId() {
        handleUpsertFaceId();
    }

    @FXML
    private void handleModifyFaceId() {
        handleUpsertFaceId();
    }

    @FXML
    private void handleDeleteFaceId() {
        User targetUser = userBox.getValue();
        if (targetUser == null) {
            setMessage("Veuillez selectionner un utilisateur.", false);
            return;
        }

        String result = userService.deleteFaceIdByAdmin(UserSession.getCurrentUserRole(), targetUser.getEmail());
        boolean success = result.startsWith("Face ID supprime");
        setMessage(result, success);
        refreshFaceStatus(targetUser);
    }

    @FXML
    private void goBack() {
        SceneNavigator.navigate(userBox, "/Welcome.fxml", message -> setMessage(message, false));
    }

    private void handleUpsertFaceId() {
        User targetUser = userBox.getValue();
        if (targetUser == null) {
            setMessage("Veuillez selectionner un utilisateur.", false);
            return;
        }
        if (selectedImageFile == null) {
            setMessage("Veuillez choisir une image avant l'operation.", false);
            return;
        }

        String result = userService.addOrUpdateFaceIdByAdmin(
                UserSession.getCurrentUserRole(),
                targetUser.getEmail(),
                selectedImageFile.toPath()
        );
        boolean success = result.startsWith("Face ID ajoute") || result.startsWith("Face ID mis a jour");
        setMessage(result, success);
        refreshFaceStatus(targetUser);
    }

    private void refreshFaceStatus(User user) {
        if (user == null) {
            faceIdStatusLabel.setText("Aucun utilisateur selectionne.");
            return;
        }

        boolean enabled = userService.hasFaceId(user.getEmail());
        String status = enabled ? "ACTIVE" : "NON CONFIGURE";
        faceIdStatusLabel.setText("Face ID: " + status + " | " + user.getEmail() + " (" + user.getAdminType() + ")");
    }

    private void setMessage(String message, boolean success) {
        messageLabel.getStyleClass().removeAll("status-success", "status-error");
        messageLabel.getStyleClass().add(success ? "status-success" : "status-error");
        messageLabel.setText(message);
    }

    private void setEditingEnabled(boolean enabled) {
        userBox.setDisable(!enabled);
    }
}

package controllers;

import entities.User;
import javafx.fxml.FXML;
import javafx.scene.control.Label;
import javafx.scene.control.PasswordField;
import javafx.scene.control.TextField;
import javafx.stage.FileChooser;
import services.CompreFaceFaceIdService;
import services.UserService;
import utils.SceneNavigator;

import java.io.File;

public class FaceIdEnrollController {
    @FXML
    private TextField emailField;

    @FXML
    private PasswordField passwordField;

    @FXML
    private Label selectedImageLabel;

    @FXML
    private Label messageLabel;

    private final UserService userService = new UserService();
    private final CompreFaceFaceIdService faceIdService = new CompreFaceFaceIdService();

    private File selectedImageFile;

    @FXML
    private void handlePickImage() {
        FileChooser chooser = new FileChooser();
        chooser.setTitle("Choisir une image de visage");
        chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter(
                "Images", "*.png", "*.jpg", "*.jpeg", "*.bmp", "*.webp"
        ));
        File file = chooser.showOpenDialog(emailField.getScene() == null ? null : emailField.getScene().getWindow());
        if (file == null) {
            return;
        }
        selectedImageFile = file;
        selectedImageLabel.setText(file.getName());
    }

    @FXML
    private void handleEnrollFaceId() {
        if (!faceIdService.isConfigured()) {
            showError("CompreFace n'est pas configure.");
            return;
        }

        if (selectedImageFile == null) {
            showError("Veuillez choisir une image avant l'enrollement.");
            return;
        }

        String email = emailField.getText() == null ? "" : emailField.getText().trim().toLowerCase();
        String password = passwordField.getText() == null ? "" : passwordField.getText();

        User user = userService.login(email, password);
        if (user == null) {
            showError("Email ou mot de passe invalide.");
            return;
        }

        String faceSubject = userService.getOrCreateFaceSubject(user.getEmail());
        if (faceSubject == null || faceSubject.isBlank()) {
            showError("Impossible de preparer le profil Face ID.");
            return;
        }

        CompreFaceFaceIdService.EnrollResult result = faceIdService.enrollFace(faceSubject, selectedImageFile.toPath());
        if (!result.success()) {
            showError(result.message());
            return;
        }

        showSuccess("Face ID enregistre. Vous pouvez vous connecter sans email.");
    }

    @FXML
    private void goBackToLogin() {
        SceneNavigator.navigate(emailField, "/Login.fxml", this::showError);
    }

    private void showError(String message) {
        messageLabel.getStyleClass().removeAll("status-success", "status-error");
        messageLabel.getStyleClass().add("status-error");
        messageLabel.setText(message);
    }

    private void showSuccess(String message) {
        messageLabel.getStyleClass().removeAll("status-success", "status-error");
        messageLabel.getStyleClass().add("status-success");
        messageLabel.setText(message);
    }
}

package controllers;

import entities.User;
import javafx.concurrent.Worker;
import javafx.fxml.FXML;
import javafx.scene.control.Label;
import javafx.scene.control.PasswordField;
import javafx.scene.control.TextField;
import javafx.scene.web.WebEngine;
import javafx.scene.web.WebView;
import netscape.javascript.JSObject;
import services.RecaptchaService;
import services.UserService;
import utils.LocalRecaptchaPageServer;
import utils.RecaptchaConfig;
import utils.SceneNavigator;
import utils.UserSession;

import java.io.IOException;

public class LoginController {
    @FXML
    private TextField emailField;

    @FXML
    private PasswordField passwordField;

    @FXML
    private Label messageLabel;

    @FXML
    private WebView recaptchaView;

    private final UserService userService = new UserService();
    private final RecaptchaService recaptchaService = new RecaptchaService();
    private final LocalRecaptchaPageServer recaptchaPageServer = new LocalRecaptchaPageServer();

    @FXML
    private void initialize() {
        loadRecaptchaWidget();
    }

    @FXML
    private void handleLogin() {
        if (!RecaptchaConfig.isConfigured()) {
            showError("reCAPTCHA n'est pas configure.");
            return;
        }

        String recaptchaToken = readTokenFromWidget();
        if (recaptchaToken.isBlank()) {
            showError("Veuillez valider le reCAPTCHA avant de vous connecter.");
            return;
        }

        if (!recaptchaService.verifyToken(recaptchaToken)) {
            showError("Verification reCAPTCHA echouee. Reessayez.");
            resetCaptcha();
            return;
        }

        User user = userService.login(emailField.getText(), passwordField.getText());
        if (user == null) {
            showError("Invalid email or password.");
            return;
        }
        UserSession.setCurrentUserEmail(user.getEmail());
        UserSession.setCurrentUserRole(user.getAdminType());
        switchScene("/Welcome.fxml");
    }


    private void switchScene(String fxml) {
        SceneNavigator.navigate(emailField, fxml, this::showError);
    }

    private void showError(String message) {
        messageLabel.getStyleClass().removeAll("status-success", "status-error");
        messageLabel.getStyleClass().add("status-error");
        messageLabel.setText(message);
    }

    private void loadRecaptchaWidget() {
        WebEngine webEngine = recaptchaView.getEngine();
        webEngine.setJavaScriptEnabled(true);
        webEngine.getLoadWorker().stateProperty().addListener((obs, oldState, newState) -> {
            if (newState == Worker.State.SUCCEEDED) {
                JSObject window = (JSObject) webEngine.executeScript("window");
                window.setMember("captchaBridge", new CaptchaBridge());
            }
        });
        try {
            String recaptchaUrl = recaptchaPageServer.start(RecaptchaConfig.siteKey());
            webEngine.load(recaptchaUrl);
        } catch (IOException exception) {
            showError("Impossible de charger reCAPTCHA localement.");
        }
    }

    private void resetCaptcha() {
        recaptchaView.getEngine().executeScript("if (window.grecaptcha) { grecaptcha.reset(); }");
    }

    private String readTokenFromWidget() {
        try {
            Object token = recaptchaView.getEngine().executeScript(
                    "(window.grecaptcha && grecaptcha.getResponse) ? grecaptcha.getResponse() : ''"
            );
            return token == null ? "" : token.toString().trim();
        } catch (Exception ignored) {
            return "";
        }
    }

    public class CaptchaBridge {
        public void onToken(String token) {
            // Le token est relu depuis grecaptcha.getResponse() au moment du login.
        }
    }
}

package controllers;

import entities.User;
import javafx.concurrent.Worker;
import javafx.fxml.FXML;
import javafx.scene.control.Label;
import javafx.scene.control.PasswordField;
import javafx.scene.control.TextField;
import javafx.stage.FileChooser;
import javafx.scene.web.WebEngine;
import javafx.scene.web.WebView;
import netscape.javascript.JSObject;
import services.CompreFaceFaceIdService;
import services.RecaptchaService;
import services.UserService;
import utils.LocalRecaptchaPageServer;
import utils.RecaptchaConfig;
import utils.SceneNavigator;
import utils.UserSession;

import java.io.File;
import java.io.IOException;

public class LoginController {
    @FXML
    private TextField emailField;

    @FXML
    private PasswordField passwordField;

    @FXML
    private Label messageLabel;

    @FXML
    private WebView recaptchaView;

    private final UserService userService = new UserService();
    private final RecaptchaService recaptchaService = new RecaptchaService();
    private final LocalRecaptchaPageServer recaptchaPageServer = new LocalRecaptchaPageServer();
    private final CompreFaceFaceIdService faceIdService = new CompreFaceFaceIdService();

    @FXML
    private void initialize() {
        loadRecaptchaWidget();
    }

    @FXML
    private void handleLogin() {
        if (!RecaptchaConfig.isConfigured()) {
            showError("reCAPTCHA n'est pas configure.");
            return;
        }

        String recaptchaToken = readTokenFromWidget();
        if (recaptchaToken.isBlank()) {
            showError("Veuillez valider le reCAPTCHA avant de vous connecter.");
            return;
        }

        if (!recaptchaService.verifyToken(recaptchaToken)) {
            showError("Verification reCAPTCHA echouee. Reessayez.");
            resetCaptcha();
            return;
        }

        User user = userService.login(emailField.getText(), passwordField.getText());
        if (user == null) {
            showError("Invalid email or password.");
            return;
        }
        UserSession.setCurrentUserEmail(user.getEmail());
        UserSession.setCurrentUserRole(user.getAdminType());
        switchScene("/Welcome.fxml");
    }

    @FXML
    private void handleFaceLogin() {
        if (!faceIdService.isConfigured()) {
            showError("CompreFace n'est pas configure.");
            return;
        }

        File imageFile = pickFaceImage();
        if (imageFile == null) {
            showError("Selection d'image annulee.");
            return;
        }

        CompreFaceFaceIdService.RecognitionResult recognitionResult =
                faceIdService.recognizeByImage(imageFile.toPath());

        if (recognitionResult.status() != CompreFaceFaceIdService.RecognitionStatus.MATCH) {
            showError(recognitionResult.message());
            return;
        }

        User user = userService.findByFaceSubject(recognitionResult.subject());
        if (user == null) {
            showError("Visage reconnu, mais aucun compte local n'est associe.");
            return;
        }

        UserSession.setCurrentUserEmail(user.getEmail());
        UserSession.setCurrentUserRole(user.getAdminType());
        switchScene("/Welcome.fxml");
    }

    @FXML
    private void openFaceEnrollment() {
        switchScene("/FaceIdEnroll.fxml");
    }


    private void switchScene(String fxml) {
        SceneNavigator.navigate(emailField, fxml, this::showError);
    }

    private void showError(String message) {
        messageLabel.getStyleClass().removeAll("status-success", "status-error");
        messageLabel.getStyleClass().add("status-error");
        messageLabel.setText(message);
    }

    private File pickFaceImage() {
        FileChooser chooser = new FileChooser();
        chooser.setTitle("Choisir une image de visage");
        chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter(
                "Images", "*.png", "*.jpg", "*.jpeg", "*.bmp", "*.webp"
        ));
        return chooser.showOpenDialog(emailField.getScene() == null ? null : emailField.getScene().getWindow());
    }

    private void loadRecaptchaWidget() {
        WebEngine webEngine = recaptchaView.getEngine();
        webEngine.setJavaScriptEnabled(true);
        webEngine.getLoadWorker().stateProperty().addListener((obs, oldState, newState) -> {
            if (newState == Worker.State.SUCCEEDED) {
                JSObject window = (JSObject) webEngine.executeScript("window");
                window.setMember("captchaBridge", new CaptchaBridge());
            }
        });
        try {
            String recaptchaUrl = recaptchaPageServer.start(RecaptchaConfig.siteKey());
            webEngine.load(recaptchaUrl);
        } catch (IOException exception) {
            showError("Impossible de charger reCAPTCHA localement.");
        }
    }

    private void resetCaptcha() {
        recaptchaView.getEngine().executeScript("if (window.grecaptcha) { grecaptcha.reset(); }");
    }

    private String readTokenFromWidget() {
        try {
            Object token = recaptchaView.getEngine().executeScript(
                    "(window.grecaptcha && grecaptcha.getResponse) ? grecaptcha.getResponse() : ''"
            );
            return token == null ? "" : token.toString().trim();
        } catch (Exception ignored) {
            return "";
        }
    }

    public class CaptchaBridge {
        public void onToken(String token) {
            // Le token est relu depuis grecaptcha.getResponse() au moment du login.
        }
    }
}

package controllers;

import entities.User;
import javafx.fxml.FXML;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import utils.SceneNavigator;
import utils.UserSession;

public class WelcomeController {
    @FXML
    private Label messageLabel;

    @FXML
    private Button manageAccountsButton;

    @FXML
    private Button manageAccountsShortcutButton;

    @FXML
    private Button modifyCredentialsNavButton;

    @FXML
    private Button modifyCredentialsButton;

    @FXML
    public void initialize() {
        User.AdminType role = UserSession.getCurrentUserRole();
        String roleLabel = role == null ? "UNKNOWN" : role.name();
        messageLabel.setText("Welcome to Bladna application\nRole: " + roleLabel);

        boolean isAdmin = role == User.AdminType.ADMIN_ACCOUNT;
        manageAccountsButton.setVisible(isAdmin);
        manageAccountsButton.setManaged(isAdmin);
        manageAccountsShortcutButton.setVisible(isAdmin);
        manageAccountsShortcutButton.setManaged(isAdmin);
        modifyCredentialsNavButton.setVisible(isAdmin);
        modifyCredentialsNavButton.setManaged(isAdmin);
        modifyCredentialsButton.setVisible(isAdmin);
        modifyCredentialsButton.setManaged(isAdmin);
    }

    @FXML
    private void goToModifyCredentials() {
        switchScene("/ModifyCredentials.fxml");
    }

    @FXML
    private void goToDeleteAccount() {
        switchScene("/DeleteAccount.fxml");
    }

    @FXML
    private void goToManageAccounts() {
        if (UserSession.getCurrentUserRole() != User.AdminType.ADMIN_ACCOUNT) {
            messageLabel.setText("Access denied: admin role required.");
            return;
        }
        switchScene("/AdminAccounts.fxml");
    }

    @FXML
    private void logout() {
        UserSession.clear();
        switchScene("/Login.fxml");
    }

    private void switchScene(String fxml) {
        SceneNavigator.navigate(messageLabel, fxml, messageLabel::setText);
    }
}

package controllers;

import entities.User;
import javafx.fxml.FXML;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import utils.SceneNavigator;
import utils.UserSession;

public class WelcomeController {
    @FXML
    private Label messageLabel;

    @FXML
    private Button manageAccountsButton;

    @FXML
    private Button manageAccountsShortcutButton;

    @FXML
    private Button modifyCredentialsNavButton;

    @FXML
    private Button modifyCredentialsButton;

    @FXML
    private Button manageFaceIdButton;

    @FXML
    private Button manageFaceIdShortcutButton;

    @FXML
    public void initialize() {
        User.AdminType role = UserSession.getCurrentUserRole();
        String roleLabel = role == null ? "UNKNOWN" : role.name();
        messageLabel.setText("Welcome to Bladna application\nRole: " + roleLabel);

        boolean isAdmin = role == User.AdminType.ADMIN_ACCOUNT;
        manageAccountsButton.setVisible(isAdmin);
        manageAccountsButton.setManaged(isAdmin);
        manageAccountsShortcutButton.setVisible(isAdmin);
        manageAccountsShortcutButton.setManaged(isAdmin);
        modifyCredentialsNavButton.setVisible(isAdmin);
        modifyCredentialsNavButton.setManaged(isAdmin);
        modifyCredentialsButton.setVisible(isAdmin);
        modifyCredentialsButton.setManaged(isAdmin);
        manageFaceIdButton.setVisible(isAdmin);
        manageFaceIdButton.setManaged(isAdmin);
        manageFaceIdShortcutButton.setVisible(isAdmin);
        manageFaceIdShortcutButton.setManaged(isAdmin);
    }

    @FXML
    private void goToModifyCredentials() {
        switchScene("/ModifyCredentials.fxml");
    }

    @FXML
    private void goToDeleteAccount() {
        switchScene("/DeleteAccount.fxml");
    }

    @FXML
    private void goToManageAccounts() {
        if (UserSession.getCurrentUserRole() != User.AdminType.ADMIN_ACCOUNT) {
            messageLabel.setText("Access denied: admin role required.");
            return;
        }
        switchScene("/AdminAccounts.fxml");
    }

    @FXML
    private void goToManageFaceId() {
        if (UserSession.getCurrentUserRole() != User.AdminType.ADMIN_ACCOUNT) {
            messageLabel.setText("Access denied: admin role required.");
            return;
        }
        switchScene("/FaceIdAdminManagement.fxml");
    }

    @FXML
    private void logout() {
        UserSession.clear();
        switchScene("/Login.fxml");
    }

    private void switchScene(String fxml) {
        SceneNavigator.navigate(messageLabel, fxml, messageLabel::setText);
    }
}

package services;

import utils.CompreFaceConfig;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.UUID;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class CompreFaceFaceIdService {
    private static final Pattern SIMILARITY_PATTERN = Pattern.compile("\"similarity\"\\s*:\\s*([0-9]*\\.?[0-9]+)");
    private static final Pattern SUBJECT_PATTERN = Pattern.compile("\"subject\"\\s*:\\s*\"([^\"]+)\"");

    private final HttpClient httpClient;

    public CompreFaceFaceIdService() {
        this(HttpClient.newHttpClient());
    }

    CompreFaceFaceIdService(HttpClient httpClient) {
        this.httpClient = httpClient;
    }

    public boolean isConfigured() {
        return CompreFaceConfig.isConfigured();
    }

    public VerificationResult verifyByEmailAndImage(String email, Path imagePath) {
        if (!isConfigured()) {
            return VerificationResult.error("CompreFace n'est pas configure.");
        }
        if (isBlank(email)) {
            return VerificationResult.error("Email requis pour la verification Face ID.");
        }
        if (imagePath == null || !Files.exists(imagePath)) {
            return VerificationResult.error("Image introuvable.");
        }

        try {
            MultipartPayload payload = buildMultipartPayload(email.trim().toLowerCase(), imagePath);
            HttpRequest request = HttpRequest.newBuilder()
                    .uri(URI.create(CompreFaceConfig.baseUrl() + "/api/v1/recognition/verify"))
                    .header("x-api-key", CompreFaceConfig.apiKey())
                    .header("Content-Type", "multipart/form-data; boundary=" + payload.boundary)
                    .POST(HttpRequest.BodyPublishers.ofByteArray(payload.body))
                    .build();

            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
            if (response.statusCode() < 200 || response.statusCode() >= 300) {
                return VerificationResult.error("CompreFace a repondu avec HTTP " + response.statusCode() + ".");
            }

            return parseVerifyResponse(email.trim().toLowerCase(), response.body());
        } catch (InterruptedException exception) {
            Thread.currentThread().interrupt();
            return VerificationResult.error("Impossible de contacter CompreFace.");
        } catch (IOException exception) {
            return VerificationResult.error("Impossible de contacter CompreFace.");
        }
    }

    public EnrollResult enrollFace(String subject, Path imagePath) {
        if (!isConfigured()) {
            return EnrollResult.error("CompreFace n'est pas configure.");
        }
        if (isBlank(subject)) {
            return EnrollResult.error("Subject Face ID invalide.");
        }
        if (imagePath == null || !Files.exists(imagePath)) {
            return EnrollResult.error("Image introuvable.");
        }

        try {
            MultipartPayload payload = buildMultipartPayload(subject.trim(), imagePath);
            HttpRequest request = HttpRequest.newBuilder()
                    .uri(URI.create(CompreFaceConfig.baseUrl() + "/api/v1/recognition/faces"))
                    .header("x-api-key", CompreFaceConfig.apiKey())
                    .header("Content-Type", "multipart/form-data; boundary=" + payload.boundary)
                    .POST(HttpRequest.BodyPublishers.ofByteArray(payload.body))
                    .build();

            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
            if (response.statusCode() < 200 || response.statusCode() >= 300) {
                return EnrollResult.error("Enrollement echoue, HTTP " + response.statusCode() + ".");
            }
            if (response.body() == null || response.body().contains("\"result\":[]")) {
                return EnrollResult.error("Aucun visage detecte pour l'enrollement.");
            }
            return EnrollResult.successResult();
        } catch (InterruptedException exception) {
            Thread.currentThread().interrupt();
            return EnrollResult.error("Impossible de contacter CompreFace.");
        } catch (IOException exception) {
            return EnrollResult.error("Impossible de contacter CompreFace.");
        }
    }

    public RecognitionResult recognizeByImage(Path imagePath) {
        if (!isConfigured()) {
            return RecognitionResult.error("CompreFace n'est pas configure.");
        }
        if (imagePath == null || !Files.exists(imagePath)) {
            return RecognitionResult.error("Image introuvable.");
        }

        try {
            MultipartPayload payload = buildMultipartPayload("recognize", imagePath);
            HttpRequest request = HttpRequest.newBuilder()
                    .uri(URI.create(CompreFaceConfig.baseUrl() + "/api/v1/recognition/recognize"))
                    .header("x-api-key", CompreFaceConfig.apiKey())
                    .header("Content-Type", "multipart/form-data; boundary=" + payload.boundary)
                    .POST(HttpRequest.BodyPublishers.ofByteArray(payload.body))
                    .build();

            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
            if (response.statusCode() < 200 || response.statusCode() >= 300) {
                return RecognitionResult.error("Reconnaissance echouee, HTTP " + response.statusCode() + ".");
            }
            return parseRecognizeResponse(response.body());
        } catch (InterruptedException exception) {
            Thread.currentThread().interrupt();
            return RecognitionResult.error("Impossible de contacter CompreFace.");
        } catch (IOException exception) {
            return RecognitionResult.error("Impossible de contacter CompreFace.");
        }
    }

    static VerificationResult parseVerifyResponse(String email, String responseBody) {
        if (responseBody == null || responseBody.isBlank()) {
            return VerificationResult.error("Reponse vide de CompreFace.");
        }

        if (responseBody.contains("\"result\":[]")) {
            return VerificationResult.noFace("Aucun visage detecte sur l'image.");
        }

        boolean hasSubject = responseBody.contains("\"subject\":\"" + escapeJson(email) + "\"");
        double similarity = findBestSimilarity(responseBody);

        if (hasSubject && similarity >= CompreFaceConfig.similarityThreshold()) {
            return VerificationResult.match(similarity);
        }

        if (responseBody.contains("\"subjects\":[]")) {
            return VerificationResult.noMatch("Visage detecte mais non reconnu pour cet email.");
        }

        if (similarity < 0) {
            return VerificationResult.noMatch("Impossible d'identifier un match valide.");
        }

        return VerificationResult.noMatch("Correspondance faciale insuffisante.");
    }

    static double findBestSimilarity(String responseBody) {
        Matcher matcher = SIMILARITY_PATTERN.matcher(responseBody);
        double best = -1.0;
        while (matcher.find()) {
            double similarity = Double.parseDouble(matcher.group(1));
            if (similarity > best) {
                best = similarity;
            }
        }
        return best;
    }

    static RecognitionResult parseRecognizeResponse(String responseBody) {
        if (responseBody == null || responseBody.isBlank()) {
            return RecognitionResult.error("Reponse vide de CompreFace.");
        }
        if (responseBody.contains("\"result\":[]")) {
            return RecognitionResult.noFace("Aucun visage detecte sur l'image.");
        }

        Matcher subjectMatcher = SUBJECT_PATTERN.matcher(responseBody);
        if (!subjectMatcher.find()) {
            return RecognitionResult.noMatch("Aucun visage connu reconnu.");
        }

        String subject = subjectMatcher.group(1);
        double similarity = findBestSimilarity(responseBody);
        if (similarity < CompreFaceConfig.similarityThreshold()) {
            return RecognitionResult.noMatch("Visage detecte mais confiance insuffisante.");
        }
        return RecognitionResult.match(subject, similarity);
    }

    private MultipartPayload buildMultipartPayload(String email, Path imagePath) throws IOException {
        String boundary = "----JavaFaceBoundary" + UUID.randomUUID();
        String fileName = imagePath.getFileName().toString();

        ByteArrayOutputStream output = new ByteArrayOutputStream();
        writeTextPart(output, boundary, "subject", email);
        writeFilePart(output, boundary, "file", fileName, Files.readAllBytes(imagePath));
        output.write(("--" + boundary + "--\r\n").getBytes(StandardCharsets.UTF_8));

        return new MultipartPayload(boundary, output.toByteArray());
    }

    private void writeTextPart(ByteArrayOutputStream output, String boundary, String name, String value) throws IOException {
        output.write(("--" + boundary + "\r\n").getBytes(StandardCharsets.UTF_8));
        output.write(("Content-Disposition: form-data; name=\"" + name + "\"\r\n").getBytes(StandardCharsets.UTF_8));
        output.write("Content-Type: text/plain; charset=UTF-8\r\n\r\n".getBytes(StandardCharsets.UTF_8));
        output.write(value.getBytes(StandardCharsets.UTF_8));
        output.write("\r\n".getBytes(StandardCharsets.UTF_8));
    }

    private void writeFilePart(ByteArrayOutputStream output, String boundary, String partName, String fileName, byte[] fileBytes) throws IOException {
        output.write(("--" + boundary + "\r\n").getBytes(StandardCharsets.UTF_8));
        output.write(("Content-Disposition: form-data; name=\"" + partName + "\"; filename=\"" + fileName + "\"\r\n").getBytes(StandardCharsets.UTF_8));
        output.write("Content-Type: application/octet-stream\r\n\r\n".getBytes(StandardCharsets.UTF_8));
        output.write(fileBytes);
        output.write("\r\n".getBytes(StandardCharsets.UTF_8));
    }

    private static String escapeJson(String value) {
        return value.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }

    private static final class MultipartPayload {
        private final String boundary;
        private final byte[] body;

        private MultipartPayload(String boundary, byte[] body) {
            this.boundary = boundary;
            this.body = body;
        }
    }

    public enum VerificationStatus {
        MATCH,
        NO_MATCH,
        NO_FACE,
        ERROR
    }

    public static final class VerificationResult {
        private final VerificationStatus status;
        private final String message;
        private final double similarity;

        private VerificationResult(VerificationStatus status, String message, double similarity) {
            this.status = status;
            this.message = message;
            this.similarity = similarity;
        }

        public static VerificationResult match(double similarity) {
            return new VerificationResult(VerificationStatus.MATCH, "Face reconnue.", similarity);
        }

        public static VerificationResult noMatch(String message) {
            return new VerificationResult(VerificationStatus.NO_MATCH, message, -1.0);
        }

        public static VerificationResult noFace(String message) {
            return new VerificationResult(VerificationStatus.NO_FACE, message, -1.0);
        }

        public static VerificationResult error(String message) {
            return new VerificationResult(VerificationStatus.ERROR, message, -1.0);
        }

        public VerificationStatus status() {
            return status;
        }

        public String message() {
            return message;
        }

        public double similarity() {
            return similarity;
        }
    }

    public enum RecognitionStatus {
        MATCH,
        NO_MATCH,
        NO_FACE,
        ERROR
    }

    public static final class RecognitionResult {
        private final RecognitionStatus status;
        private final String message;
        private final String subject;
        private final double similarity;

        private RecognitionResult(RecognitionStatus status, String message, String subject, double similarity) {
            this.status = status;
            this.message = message;
            this.subject = subject;
            this.similarity = similarity;
        }

        public static RecognitionResult match(String subject, double similarity) {
            return new RecognitionResult(RecognitionStatus.MATCH, "Face reconnue.", subject, similarity);
        }

        public static RecognitionResult noMatch(String message) {
            return new RecognitionResult(RecognitionStatus.NO_MATCH, message, null, -1.0);
        }

        public static RecognitionResult noFace(String message) {
            return new RecognitionResult(RecognitionStatus.NO_FACE, message, null, -1.0);
        }

        public static RecognitionResult error(String message) {
            return new RecognitionResult(RecognitionStatus.ERROR, message, null, -1.0);
        }

        public RecognitionStatus status() {
            return status;
        }

        public String message() {
            return message;
        }

        public String subject() {
            return subject;
        }

        public double similarity() {
            return similarity;
        }
    }

    public static final class EnrollResult {
        private final boolean success;
        private final String message;

        private EnrollResult(boolean success, String message) {
            this.success = success;
            this.message = message;
        }

        public static EnrollResult successResult() {
            return new EnrollResult(true, "Face ID enregistre avec succes.");
        }

        public static EnrollResult error(String message) {
            return new EnrollResult(false, message);
        }

        public boolean success() {
            return success;
        }

        public String message() {
            return message;
        }
    }
}

package services;

import entities.User;
import org.mindrot.jbcrypt.BCrypt;
import utils.MyDataBase;

import java.util.Collections;
import java.util.List;
import java.util.regex.Pattern;

public class UserService {
    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+$");
    private static final int MIN_NAME_LENGTH = 3;
    private static final int MIN_PASSWORD_LENGTH = 8;
    private final MyDataBase dataBase = MyDataBase.getInstance();

    public User login(String email, String password) {
        if (isBlank(email) || isBlank(password)) {
            return null;
        }

        User user = dataBase.findByEmail(email);
        if (user == null) {
            return null;
        }

        String storedPassword = user.getPasswordHash();
        if (verifyPassword(password, storedPassword)) {
            return user;
        }

        if (password.equals(storedPassword)) {
            String migratedHash = hashPassword(password);
            boolean migrated = dataBase.updateUserCredentials(user.getAdminType(), user.getEmail(), user.getEmail(), migratedHash);
            if (migrated) {
                return new User(user.getFirstName(), user.getLastName(), user.getEmail(), migratedHash, user.getAdminType());
            }
        }
        return null;
    }

    public String createAccountByAdmin(User.AdminType currentRole,
                                       String firstName,
                                       String lastName,
                                       String email,
                                       String password,
                                       User.AdminType targetRole) {
        if (currentRole != User.AdminType.ADMIN_ACCOUNT) {
            return "Only admin accounts can create new accounts.";
        }
        if (isBlank(firstName) || isBlank(lastName) || isBlank(email) || isBlank(password) || targetRole == null) {
            return "All fields are required.";
        }
        if (!EMAIL_PATTERN.matcher(email.trim()).matches()) {
            return "Invalid email format.";
        }
        if (!hasMinLength(firstName, MIN_NAME_LENGTH) || !hasMinLength(lastName, MIN_NAME_LENGTH)) {
            return "First name and last name must be at least 3 characters.";
        }
        if (!hasMinLength(password, MIN_PASSWORD_LENGTH)) {
            return "Password must be at least 8 characters.";
        }

        String passwordHash = hashPassword(password);
        User user = new User(firstName.trim(), lastName.trim(), email.trim().toLowerCase(), passwordHash, targetRole);
        boolean saved = dataBase.addUser(user);
        if (!saved) {
            return "Email already exists.";
        }

        return "SUCCESS";
    }

    public String updateCredentials(User.AdminType role, String currentEmail, String newEmail, String newPassword) {
        if (role == null || isBlank(currentEmail) || isBlank(newEmail) || isBlank(newPassword)) {
            return "All fields are required.";
        }
        if (!EMAIL_PATTERN.matcher(newEmail.trim()).matches()) {
            return "Invalid email format.";
        }

        if (!hasMinLength(newPassword, MIN_PASSWORD_LENGTH)) {
            return "Password must be at least 8 characters.";
        }

        boolean updated = dataBase.updateUserCredentials(role, currentEmail, newEmail, hashPassword(newPassword));
        if (!updated) {
            return "Unable to update credentials.";
        }
        return "SUCCESS";
    }

    public List<User> getUsersEditableByCurrentUser(User.AdminType currentRole) {
        if (currentRole != User.AdminType.ADMIN_ACCOUNT) {
            return Collections.emptyList();
        }
        return dataBase.findAllUsers();
    }

    public String updateCredentialsByAdmin(User.AdminType currentRole,
                                           String targetCurrentEmail,
                                           User.AdminType targetRole,
                                           String newFirstName,
                                           String newLastName,
                                           String newEmail,
                                           String newPassword) {
        if (currentRole != User.AdminType.ADMIN_ACCOUNT) {
            return "Only admin can modify credentials.";
        }
        if (targetRole == null
                || isBlank(targetCurrentEmail)
                || isBlank(newFirstName)
                || isBlank(newLastName)
                || isBlank(newEmail)) {
            return "All fields are required.";
        }
        if (!EMAIL_PATTERN.matcher(newEmail.trim()).matches()) {
            return "Invalid email format.";
        }
        if (!hasMinLength(newFirstName, MIN_NAME_LENGTH) || !hasMinLength(newLastName, MIN_NAME_LENGTH)) {
            return "First name and last name must be at least 3 characters.";
        }

        if (!isBlank(newPassword) && !hasMinLength(newPassword, MIN_PASSWORD_LENGTH)) {
            return "Password must be at least 8 characters.";
        }

        User targetUser = dataBase.findByEmail(targetCurrentEmail);
        if (targetUser == null) {
            return "Target account not found.";
        }

        String passwordToStore = isBlank(newPassword) ? targetUser.getPasswordHash() : hashPassword(newPassword);

        boolean updated = dataBase.updateUserProfileByTarget(
                targetRole,
                targetCurrentEmail,
                newFirstName,
                newLastName,
                newEmail,
                passwordToStore
        );
        if (!updated) {
            return "Unable to update profile.";
        }
        return "SUCCESS";
    }

    public boolean deleteAccount(User.AdminType role, String email) {
        if (role == null || isBlank(email)) {
            return false;
        }

        if (role == User.AdminType.ADMIN_ACCOUNT && !dataBase.hasAnotherAdmin(email)) {
            return false;
        }

        return dataBase.deleteUserByEmail(role, email);
    }

    public boolean deleteAccountByAdmin(String targetEmail) {
        if (isBlank(targetEmail)) {
            return false;
        }

        User targetUser = dataBase.findByEmail(targetEmail);
        if (targetUser == null) {
            return false;
        }

        if (targetUser.getAdminType() == User.AdminType.ADMIN_ACCOUNT && !dataBase.hasAnotherAdmin(targetUser.getEmail())) {
            return false;
        }

        return dataBase.deleteUserByEmail(targetUser.getAdminType(), targetUser.getEmail());
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }

    private boolean hasMinLength(String value, int minLength) {
        return value != null && value.trim().length() >= minLength;
    }

    private String hashPassword(String plainPassword) {
        return BCrypt.hashpw(plainPassword, BCrypt.gensalt());
    }

    private boolean verifyPassword(String plainPassword, String storedPassword) {
        if (isBlank(storedPassword)) {
            return false;
        }
        if (!isBcryptHash(storedPassword)) {
            return false;
        }
        return BCrypt.checkpw(plainPassword, storedPassword);
    }

    private boolean isBcryptHash(String value) {
        return value.startsWith("$2a$") || value.startsWith("$2b$") || value.startsWith("$2y$");
    }
}

package services;

import entities.User;
import org.mindrot.jbcrypt.BCrypt;
import utils.MyDataBase;

import java.nio.file.Path;
import java.util.Collections;
import java.util.List;
import java.util.UUID;
import java.util.regex.Pattern;

public class UserService {
    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+$");
    private static final int MIN_NAME_LENGTH = 3;
    private static final int MIN_PASSWORD_LENGTH = 8;
    private final MyDataBase dataBase = MyDataBase.getInstance();
    private final CompreFaceFaceIdService faceIdService = new CompreFaceFaceIdService();

    public User findByEmail(String email) {
        if (isBlank(email)) {
            return null;
        }
        return dataBase.findByEmail(email.trim().toLowerCase());
    }

    public User findByFaceSubject(String faceSubject) {
        if (isBlank(faceSubject)) {
            return null;
        }
        String email = dataBase.findEmailByFaceSubject(faceSubject.trim());
        if (isBlank(email)) {
            return null;
        }
        return dataBase.findByEmail(email);
    }

    public String getOrCreateFaceSubject(String email) {
        if (isBlank(email)) {
            return null;
        }

        String normalizedEmail = email.trim().toLowerCase();
        String existingSubject = dataBase.findFaceSubjectByEmail(normalizedEmail);
        if (!isBlank(existingSubject)) {
            return existingSubject;
        }

        String subject = "usr_" + UUID.randomUUID();
        boolean linked = dataBase.upsertFaceProfile(normalizedEmail, subject);
        return linked ? subject : null;
    }

    public boolean hasFaceId(String email) {
        if (isBlank(email)) {
            return false;
        }
        return dataBase.hasFaceProfileByEmail(email.trim().toLowerCase());
    }

    public String addOrUpdateFaceIdByAdmin(User.AdminType currentRole, String targetEmail, Path imagePath) {
        if (currentRole != User.AdminType.ADMIN_ACCOUNT) {
            return "Access denied: admin role required.";
        }
        if (isBlank(targetEmail)) {
            return "Target email is required.";
        }
        if (imagePath == null) {
            return "Image requise.";
        }
        if (!faceIdService.isConfigured()) {
            return "CompreFace n'est pas configure.";
        }

        User targetUser = findByEmail(targetEmail);
        if (targetUser == null) {
            return "Target account not found.";
        }

        boolean hadFaceId = hasFaceId(targetUser.getEmail());
        String subject = getOrCreateFaceSubject(targetUser.getEmail());
        if (isBlank(subject)) {
            return "Impossible de preparer le subject Face ID.";
        }

        CompreFaceFaceIdService.EnrollResult enrollResult = faceIdService.enrollFace(subject, imagePath);
        if (!enrollResult.success()) {
            return enrollResult.message();
        }

        return hadFaceId
                ? "Face ID mis a jour avec succes pour " + targetUser.getEmail() + "."
                : "Face ID ajoute avec succes pour " + targetUser.getEmail() + ".";
    }

    public String deleteFaceIdByAdmin(User.AdminType currentRole, String targetEmail) {
        if (currentRole != User.AdminType.ADMIN_ACCOUNT) {
            return "Access denied: admin role required.";
        }
        if (isBlank(targetEmail)) {
            return "Target email is required.";
        }

        User targetUser = findByEmail(targetEmail);
        if (targetUser == null) {
            return "Target account not found.";
        }

        boolean removed = dataBase.removeFaceProfileByEmail(targetUser.getEmail());
        if (!removed) {
            return "Aucun Face ID actif a supprimer pour cet utilisateur.";
        }
        return "Face ID supprime pour " + targetUser.getEmail() + ".";
    }

    public User login(String email, String password) {
        if (isBlank(email) || isBlank(password)) {
            return null;
        }

        User user = dataBase.findByEmail(email);
        if (user == null) {
            return null;
        }

        String storedPassword = user.getPasswordHash();
        if (verifyPassword(password, storedPassword)) {
            return user;
        }

        if (password.equals(storedPassword)) {
            String migratedHash = hashPassword(password);
            boolean migrated = dataBase.updateUserCredentials(user.getAdminType(), user.getEmail(), user.getEmail(), migratedHash);
            if (migrated) {
                return new User(user.getFirstName(), user.getLastName(), user.getEmail(), migratedHash, user.getAdminType());
            }
        }
        return null;
    }

    public String createAccountByAdmin(User.AdminType currentRole,
                                       String firstName,
                                       String lastName,
                                       String email,
                                       String password,
                                       User.AdminType targetRole) {
        if (currentRole != User.AdminType.ADMIN_ACCOUNT) {
            return "Only admin accounts can create new accounts.";
        }
        if (isBlank(firstName) || isBlank(lastName) || isBlank(email) || isBlank(password) || targetRole == null) {
            return "All fields are required.";
        }
        if (!EMAIL_PATTERN.matcher(email.trim()).matches()) {
            return "Invalid email format.";
        }
        if (!hasMinLength(firstName, MIN_NAME_LENGTH) || !hasMinLength(lastName, MIN_NAME_LENGTH)) {
            return "First name and last name must be at least 3 characters.";
        }
        if (!hasMinLength(password, MIN_PASSWORD_LENGTH)) {
            return "Password must be at least 8 characters.";
        }

        String passwordHash = hashPassword(password);
        User user = new User(firstName.trim(), lastName.trim(), email.trim().toLowerCase(), passwordHash, targetRole);
        boolean saved = dataBase.addUser(user);
        if (!saved) {
            return "Email already exists.";
        }

        return "SUCCESS";
    }

    public String updateCredentials(User.AdminType role, String currentEmail, String newEmail, String newPassword) {
        if (role == null || isBlank(currentEmail) || isBlank(newEmail) || isBlank(newPassword)) {
            return "All fields are required.";
        }
        if (!EMAIL_PATTERN.matcher(newEmail.trim()).matches()) {
            return "Invalid email format.";
        }

        if (!hasMinLength(newPassword, MIN_PASSWORD_LENGTH)) {
            return "Password must be at least 8 characters.";
        }

        boolean updated = dataBase.updateUserCredentials(role, currentEmail, newEmail, hashPassword(newPassword));
        if (!updated) {
            return "Unable to update credentials.";
        }
        return "SUCCESS";
    }

    public List<User> getUsersEditableByCurrentUser(User.AdminType currentRole) {
        if (currentRole != User.AdminType.ADMIN_ACCOUNT) {
            return Collections.emptyList();
        }
        return dataBase.findAllUsers();
    }

    public String updateCredentialsByAdmin(User.AdminType currentRole,
                                           String targetCurrentEmail,
                                           User.AdminType targetRole,
                                           String newFirstName,
                                           String newLastName,
                                           String newEmail,
                                           String newPassword) {
        if (currentRole != User.AdminType.ADMIN_ACCOUNT) {
            return "Only admin can modify credentials.";
        }
        if (targetRole == null
                || isBlank(targetCurrentEmail)
                || isBlank(newFirstName)
                || isBlank(newLastName)
                || isBlank(newEmail)) {
            return "All fields are required.";
        }
        if (!EMAIL_PATTERN.matcher(newEmail.trim()).matches()) {
            return "Invalid email format.";
        }
        if (!hasMinLength(newFirstName, MIN_NAME_LENGTH) || !hasMinLength(newLastName, MIN_NAME_LENGTH)) {
            return "First name and last name must be at least 3 characters.";
        }

        if (!isBlank(newPassword) && !hasMinLength(newPassword, MIN_PASSWORD_LENGTH)) {
            return "Password must be at least 8 characters.";
        }

        User targetUser = dataBase.findByEmail(targetCurrentEmail);
        if (targetUser == null) {
            return "Target account not found.";
        }

        String passwordToStore = isBlank(newPassword) ? targetUser.getPasswordHash() : hashPassword(newPassword);

        boolean updated = dataBase.updateUserProfileByTarget(
                targetRole,
                targetCurrentEmail,
                newFirstName,
                newLastName,
                newEmail,
                passwordToStore
        );
        if (!updated) {
            return "Unable to update profile.";
        }
        return "SUCCESS";
    }

    public boolean deleteAccount(User.AdminType role, String email) {
        if (role == null || isBlank(email)) {
            return false;
        }

        if (role == User.AdminType.ADMIN_ACCOUNT && !dataBase.hasAnotherAdmin(email)) {
            return false;
        }

        return dataBase.deleteUserByEmail(role, email);
    }

    public boolean deleteAccountByAdmin(String targetEmail) {
        if (isBlank(targetEmail)) {
            return false;
        }

        User targetUser = dataBase.findByEmail(targetEmail);
        if (targetUser == null) {
            return false;
        }

        if (targetUser.getAdminType() == User.AdminType.ADMIN_ACCOUNT && !dataBase.hasAnotherAdmin(targetUser.getEmail())) {
            return false;
        }

        return dataBase.deleteUserByEmail(targetUser.getAdminType(), targetUser.getEmail());
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }

    private boolean hasMinLength(String value, int minLength) {
        return value != null && value.trim().length() >= minLength;
    }

    private String hashPassword(String plainPassword) {
        return BCrypt.hashpw(plainPassword, BCrypt.gensalt());
    }

    private boolean verifyPassword(String plainPassword, String storedPassword) {
        if (isBlank(storedPassword)) {
            return false;
        }
        if (!isBcryptHash(storedPassword)) {
            return false;
        }
        return BCrypt.checkpw(plainPassword, storedPassword);
    }

    private boolean isBcryptHash(String value) {
        return value.startsWith("$2a$") || value.startsWith("$2b$") || value.startsWith("$2y$");
    }
}

package utils;

public final class CompreFaceConfig {
    private static final String DEFAULT_PROVIDER = "compreface";
    private static final String DEFAULT_BASE_URL = "http://localhost:8000";
    private static final String DEFAULT_API_KEY = "810092e7-85de-4f3f-97b2-099709ffa5a3";
    private static final double DEFAULT_SIMILARITY_THRESHOLD = 0.75;

    private CompreFaceConfig() {
        // Utility class
    }

    public static String provider() {
        return read("FACE_RECOGNITION_PROVIDER", DEFAULT_PROVIDER).toLowerCase();
    }

    public static String baseUrl() {
        String value = read("COMPREFACE_BASE_URL", DEFAULT_BASE_URL);
        if (value.endsWith("/")) {
            return value.substring(0, value.length() - 1);
        }
        return value;
    }

    public static String apiKey() {
        return read("COMPREFACE_API_KEY", DEFAULT_API_KEY);
    }

    public static double similarityThreshold() {
        String raw = read("COMPREFACE_SIMILARITY_THRESHOLD", Double.toString(DEFAULT_SIMILARITY_THRESHOLD));
        try {
            double value = Double.parseDouble(raw);
            if (value < 0.0 || value > 1.0) {
                return DEFAULT_SIMILARITY_THRESHOLD;
            }
            return value;
        } catch (NumberFormatException ignored) {
            return DEFAULT_SIMILARITY_THRESHOLD;
        }
    }

    public static boolean isConfigured() {
        return "compreface".equals(provider())
                && !baseUrl().isBlank()
                && !apiKey().isBlank();
    }

    private static String read(String key, String defaultValue) {
        String sysValue = System.getProperty(key);
        if (sysValue != null && !sysValue.trim().isEmpty()) {
            return sysValue.trim();
        }

        String envValue = System.getenv(key);
        if (envValue != null && !envValue.trim().isEmpty()) {
            return envValue.trim();
        }

        return defaultValue;
    }
}

package utils;

import entities.User;
import org.mindrot.jbcrypt.BCrypt;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class MyDataBase {
    private static final MyDataBase INSTANCE = new MyDataBase();
    private static final String URL = "jdbc:mysql://localhost:3306/pidevjava?useSSL=false&allowPublicKeyRetrieval=true&serverTimezone=UTC";
    private static final String USERNAME = "root";
    private static final String PASSWORD = "";

    private static final String DEFAULT_ADMIN_FIRST_NAME = "Default";
    private static final String DEFAULT_ADMIN_LAST_NAME = "Admin";
    private static final String DEFAULT_ADMIN_EMAIL = "admin@bladna.local";
    private static final String DEFAULT_ADMIN_PASSWORD = "Admin123!";

    private MyDataBase() {
        ensureDefaultAdmin();
    }

    public static MyDataBase getInstance() {
        return INSTANCE;
    }

    public synchronized boolean addUser(User user) {
        String email = normalizeEmail(user.getEmail());
        if (findByEmail(email) != null) {
            return false;
        }

        String sql = "INSERT INTO " + getTableName(user.getAdminType()) + " (first_name, last_name, email, password) VALUES (?, ?, ?, ?)";
        try (Connection connection = getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setString(1, user.getFirstName());
            statement.setString(2, user.getLastName());
            statement.setString(3, email);
            statement.setString(4, user.getPasswordHash());
            return statement.executeUpdate() > 0;
        } catch (SQLException e) {
            throw new RuntimeException("Unable to insert user in database.", e);
        }
    }

    public synchronized User findByEmail(String email) {
        String normalizedEmail = normalizeEmail(email);
        User user = findByEmailInTable(normalizedEmail, "admin_accounts", User.AdminType.ADMIN_ACCOUNT);
        if (user != null) {
            return user;
        }

        user = findByEmailInTable(normalizedEmail, "event_manager", User.AdminType.EVENT_MANAGER);
        if (user != null) {
            return user;
        }

        return findByEmailInTable(normalizedEmail, "finance_manager", User.AdminType.FINANCE_MANAGER);
    }

    public synchronized List<User> findAllUsers() {
        List<User> users = new ArrayList<>();
        users.addAll(findAllUsersInTable("admin_accounts", User.AdminType.ADMIN_ACCOUNT));
        users.addAll(findAllUsersInTable("event_manager", User.AdminType.EVENT_MANAGER));
        users.addAll(findAllUsersInTable("finance_manager", User.AdminType.FINANCE_MANAGER));
        users.sort(Comparator.comparing(User::getEmail, String.CASE_INSENSITIVE_ORDER));
        return users;
    }

    public synchronized boolean updateUserCredentials(User.AdminType role, String currentEmail, String newEmail, String newPassword) {
        String normalizedCurrentEmail = normalizeEmail(currentEmail);
        String normalizedNewEmail = normalizeEmail(newEmail);

        if (!normalizedCurrentEmail.equals(normalizedNewEmail)) {
            User existingUser = findByEmail(normalizedNewEmail);
            if (existingUser != null) {
                return false;
            }
        }

        String sql = "UPDATE " + getTableName(role) + " SET email = ?, password = ? WHERE email = ?";
        try (Connection connection = getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setString(1, normalizedNewEmail);
            statement.setString(2, newPassword);
            statement.setString(3, normalizedCurrentEmail);
            return statement.executeUpdate() > 0;
        } catch (SQLException e) {
            throw new RuntimeException("Unable to update user credentials.", e);
        }
    }

    public synchronized boolean updateUserCredentialsByTarget(User.AdminType targetRole,
                                                              String targetCurrentEmail,
                                                              String newEmail,
                                                              String newPassword) {
        return updateUserCredentials(targetRole, targetCurrentEmail, newEmail, newPassword);
    }

    public synchronized boolean updateUserProfileByTarget(User.AdminType targetRole,
                                                          String targetCurrentEmail,
                                                          String newFirstName,
                                                          String newLastName,
                                                          String newEmail,
                                                          String newPassword) {
        String normalizedCurrentEmail = normalizeEmail(targetCurrentEmail);
        String normalizedNewEmail = normalizeEmail(newEmail);

        if (!normalizedCurrentEmail.equals(normalizedNewEmail)) {
            User existingUser = findByEmail(normalizedNewEmail);
            if (existingUser != null) {
                return false;
            }
        }

        String sql = "UPDATE " + getTableName(targetRole) + " SET first_name = ?, last_name = ?, email = ?, password = ? WHERE email = ?";
        try (Connection connection = getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setString(1, newFirstName == null ? "" : newFirstName.trim());
            statement.setString(2, newLastName == null ? "" : newLastName.trim());
            statement.setString(3, normalizedNewEmail);
            statement.setString(4, newPassword);
            statement.setString(5, normalizedCurrentEmail);
            return statement.executeUpdate() > 0;
        } catch (SQLException e) {
            throw new RuntimeException("Unable to update user profile.", e);
        }
    }

    public synchronized boolean deleteUserByEmail(User.AdminType role, String email) {
        String normalizedEmail = normalizeEmail(email);
        String sql = "DELETE FROM " + getTableName(role) + " WHERE email = ?";
        try (Connection connection = getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setString(1, normalizedEmail);
            return statement.executeUpdate() > 0;
        } catch (SQLException e) {
            throw new RuntimeException("Unable to delete user.", e);
        }
    }

    public synchronized boolean hasAnotherAdmin(String currentAdminEmail) {
        String normalizedEmail = normalizeEmail(currentAdminEmail);
        String sql = "SELECT COUNT(*) FROM admin_accounts WHERE email <> ?";
        try (Connection connection = getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setString(1, normalizedEmail);
            try (ResultSet resultSet = statement.executeQuery()) {
                if (resultSet.next()) {
                    return resultSet.getInt(1) > 0;
                }
                return false;
            }
        } catch (SQLException e) {
            throw new RuntimeException("Unable to verify admin count.", e);
        }
    }

    private User findByEmailInTable(String email, String table, User.AdminType role) {
        String sql = "SELECT first_name, last_name, email, password FROM " + table + " WHERE email = ?";
        try (Connection connection = getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {
            statement.setString(1, email);
            try (ResultSet resultSet = statement.executeQuery()) {
                if (resultSet.next()) {
                    return new User(
                            resultSet.getString("first_name"),
                            resultSet.getString("last_name"),
                            resultSet.getString("email"),
                            resultSet.getString("password"),
                            role
                    );
                }
                return null;
            }
        } catch (SQLException e) {
            throw new RuntimeException("Unable to fetch user by email.", e);
        }
    }

    private List<User> findAllUsersInTable(String table, User.AdminType role) {
        String sql = "SELECT first_name, last_name, email, password FROM " + table;
        List<User> users = new ArrayList<>();
        try (Connection connection = getConnection();
             PreparedStatement statement = connection.prepareStatement(sql);
             ResultSet resultSet = statement.executeQuery()) {
            while (resultSet.next()) {
                users.add(new User(
                        resultSet.getString("first_name"),
                        resultSet.getString("last_name"),
                        resultSet.getString("email"),
                        resultSet.getString("password"),
                        role
                ));
            }
            return users;
        } catch (SQLException e) {
            throw new RuntimeException("Unable to fetch all users.", e);
        }
    }

    private void ensureDefaultAdmin() {
        String checkSql = "SELECT COUNT(*) FROM admin_accounts";
        String insertSql = "INSERT INTO admin_accounts (first_name, last_name, email, password) VALUES (?, ?, ?, ?)";

        try (Connection connection = getConnection();
             PreparedStatement checkStatement = connection.prepareStatement(checkSql);
             ResultSet resultSet = checkStatement.executeQuery()) {
            if (resultSet.next() && resultSet.getInt(1) > 0) {
                return;
            }

            try (PreparedStatement insertStatement = connection.prepareStatement(insertSql)) {
                insertStatement.setString(1, DEFAULT_ADMIN_FIRST_NAME);
                insertStatement.setString(2, DEFAULT_ADMIN_LAST_NAME);
                insertStatement.setString(3, DEFAULT_ADMIN_EMAIL);
                insertStatement.setString(4, BCrypt.hashpw(DEFAULT_ADMIN_PASSWORD, BCrypt.gensalt()));
                insertStatement.executeUpdate();
            }
        } catch (SQLException e) {
            throw new RuntimeException("Unable to ensure default admin.", e);
        }
    }

    private String getTableName(User.AdminType role) {
        if (role == null) {
            throw new IllegalArgumentException("Role is required.");
        }

        switch (role) {
            case ADMIN_ACCOUNT:
                return "admin_accounts";
            case EVENT_MANAGER:
                return "event_manager";
            case FINANCE_MANAGER:
                return "finance_manager";
            default:
                throw new IllegalArgumentException("Unsupported role: " + role);
        }
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(URL, USERNAME, PASSWORD);
    }

    private String normalizeEmail(String email) {
        return email == null ? "" : email.trim().toLowerCase();
    }
}

