            throw new RuntimeException("Unable to fetch all users.", e);
        }
    }

    private void ensureDefaultAdmin() {
        String checkSql = "SELECT COUNT(*) FROM admin_accounts";
        String insertSql = "INSERT INTO admin_accounts (first_name, last_name, email, password) VALUES (?, ?, ?, ?)";

        try (Connection connection = getConnection();
             PreparedStatement checkStatement = connection.prepareStatement(checkSql);
             ResultSet resultSet = checkStatement.executeQuery()) {
            if (resultSet.next() && resultSet.getInt(1) > 0) {
                return;
            }

            try (PreparedStatement insertStatement = connection.prepareStatement(insertSql)) {
                insertStatement.setString(1, DEFAULT_ADMIN_FIRST_NAME);
                insertStatement.setString(2, DEFAULT_ADMIN_LAST_NAME);
                insertStatement.setString(3, DEFAULT_ADMIN_EMAIL);
                insertStatement.setString(4, BCrypt.hashpw(DEFAULT_ADMIN_PASSWORD, BCrypt.gensalt()));
                insertStatement.executeUpdate();
            }
        } catch (SQLException e) {
            throw new RuntimeException("Unable to ensure default admin.", e);
        }
    }

    private String getTableName(User.AdminType role) {
        if (role == null) {
            throw new IllegalArgumentException("Role is required.");
        }

        switch (role) {
            case ADMIN_ACCOUNT:
                return "admin_accounts";
            case EVENT_MANAGER:
                return "event_manager";
            case FINANCE_MANAGER:
                return "finance_manager";
            default:
                throw new IllegalArgumentException("Unsupported role: " + role);
        }
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(URL, USERNAME, PASSWORD);
    }

    private String normalizeEmail(String email) {
        return email == null ? "" : email.trim().toLowerCase();
    }

    private String normalizeSubject(String subject) {
        return subject == null ? "" : subject.trim();
    }

}

package services;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

class CompreFaceFaceIdServiceTest {

    @AfterEach
    void clearThresholdOverride() {
        System.clearProperty("COMPREFACE_SIMILARITY_THRESHOLD");
    }

    @Test
    void shouldReturnMatchWhenSubjectAndSimilarityAreValid() {
        System.setProperty("COMPREFACE_SIMILARITY_THRESHOLD", "0.70");
        String response = "{\"result\":[{\"subjects\":[{\"subject\":\"user@example.com\",\"similarity\":0.91}]}]}";

        CompreFaceFaceIdService.VerificationResult result =
                CompreFaceFaceIdService.parseVerifyResponse("user@example.com", response);

        assertEquals(CompreFaceFaceIdService.VerificationStatus.MATCH, result.status());
    }

    @Test
    void shouldReturnNoFaceWhenResultArrayIsEmpty() {
        String response = "{\"result\":[]}";

        CompreFaceFaceIdService.VerificationResult result =
                CompreFaceFaceIdService.parseVerifyResponse("user@example.com", response);

        assertEquals(CompreFaceFaceIdService.VerificationStatus.NO_FACE, result.status());
    }

    @Test
    void shouldReturnNoMatchWhenSimilarityIsTooLow() {
        System.setProperty("COMPREFACE_SIMILARITY_THRESHOLD", "0.95");
        String response = "{\"result\":[{\"subjects\":[{\"subject\":\"user@example.com\",\"similarity\":0.70}]}]}";

        CompreFaceFaceIdService.VerificationResult result =
                CompreFaceFaceIdService.parseVerifyResponse("user@example.com", response);

        assertEquals(CompreFaceFaceIdService.VerificationStatus.NO_MATCH, result.status());
    }

    @Test
    void shouldRecognizeSubjectWhenSimilarityIsAboveThreshold() {
        System.setProperty("COMPREFACE_SIMILARITY_THRESHOLD", "0.65");
        String response = "{\"result\":[{\"subjects\":[{\"subject\":\"usr_abc\",\"similarity\":0.88}]}]}";

        CompreFaceFaceIdService.RecognitionResult result =
                CompreFaceFaceIdService.parseRecognizeResponse(response);

        assertEquals(CompreFaceFaceIdService.RecognitionStatus.MATCH, result.status());
        assertEquals("usr_abc", result.subject());
    }

    @Test
    void shouldReturnNoFaceForRecognitionWhenNoFaceDetected() {
        String response = "{\"result\":[]}";

        CompreFaceFaceIdService.RecognitionResult result =
                CompreFaceFaceIdService.parseRecognizeResponse(response);

        assertEquals(CompreFaceFaceIdService.RecognitionStatus.NO_FACE, result.status());
    }
}

package utils;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class CompreFaceConfigTest {

    @AfterEach
    void clearOverrides() {
        System.clearProperty("FACE_RECOGNITION_PROVIDER");
        System.clearProperty("COMPREFACE_BASE_URL");
        System.clearProperty("COMPREFACE_API_KEY");
        System.clearProperty("COMPREFACE_SIMILARITY_THRESHOLD");
    }

    @Test
    void shouldUseLocalDefaultsWhenNoOverrideExists() {
        assertEquals("compreface", CompreFaceConfig.provider());
        assertEquals("http://localhost:8000", CompreFaceConfig.baseUrl());
        assertEquals("810092e7-85de-4f3f-97b2-099709ffa5a3", CompreFaceConfig.apiKey());
        assertEquals(0.75, CompreFaceConfig.similarityThreshold());
        assertTrue(CompreFaceConfig.isConfigured());
    }

    @Test
    void shouldReadSystemPropertyOverrides() {
        System.setProperty("COMPREFACE_BASE_URL", "http://127.0.0.1:9000/");
        System.setProperty("COMPREFACE_API_KEY", "my-test-key");
        System.setProperty("COMPREFACE_SIMILARITY_THRESHOLD", "0.85");

        assertEquals("http://127.0.0.1:9000", CompreFaceConfig.baseUrl());
        assertEquals("my-test-key", CompreFaceConfig.apiKey());
        assertEquals(0.85, CompreFaceConfig.similarityThreshold());
    }
}
